/* @lc app=leetcode id=2850 lang=kotlin */ class Solution { fun perms(l: List<Int>): List<List<Int>> = if (l.size <= 1) listOf(l) else l.indices.flatMap { i -> perms(l.take(i) + l.drop(i + 1)).map { listOf(l[i]) + it } } fun minimumMoves(grid: Array<IntArray>): Int = (0 until 9).filter { grid[it / 3][it % 3] == 0 }.let { zs -> (0 until 9).flatMap { c -> List(maxOf(0, grid[c / 3][c % 3] - 1)) { c } }.let { ex -> perms(ex).minOf { p -> zs.indices.sumOf { Math.abs(zs[it] / 3 - p[it] / 3) + Math.abs(zs[it] % 3 - p[it] % 3) } } } } }